<?php namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\Booking; use App\Models\Room; use App\Models\AppNotification; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; class BookingController extends Controller { public function index(Request $request) { $bookings = Booking::with(["user","room"])->when($request->filled("status"),function($q) use ($request) { $q->where("status",$request->input("status")); })->when($request->filled("search"),function($q) use ($request) { $s=$request->input("search"); $q->where(function($x) use ($s) { $x->whereHas("user",function($u) use ($s) { $u->where("name","like","%$s%")->orWhere("nim","like","%$s%"); })->orWhereHas("room",function($r) use ($s) { $r->where("name","like","%$s%"); }); }); })->latest("id")->paginate(10)->withQueryString(); return view("admin.bookings.index",compact("bookings")); } public function show(Booking $booking) { $booking->load(["user","room"]); return view("admin.bookings.show",compact("booking")); } public function update(Request $request, Booking $booking) { $data=$request->validate(["status"=>"required|in:processing,approved,cancelled"]); DB::transaction(function() use ($booking,$data) { $room=Room::lockForUpdate()->findOrFail($booking->room_id); $b=Booking::lockForUpdate()->findOrFail($booking->id); $allowed=["waiting"=>["processing","approved","cancelled"],"processing"=>["approved","cancelled"]]; if (!in_array($data["status"],$allowed[$b->status] ?? [],true)) { throw \Illuminate\Validation\ValidationException::withMessages(["status"=>"Perubahan status tidak diizinkan."]); } if ($data["status"]==="approved") { if (!$room->available || $b->start_date < $room->available_from) { throw \Illuminate\Validation\ValidationException::withMessages(["status"=>"Kamar tidak tersedia pada tanggal tersebut."]); } $active=Booking::where("room_id",$b->room_id)->where("id","!=",$b->id)->whereIn("status",["waiting","processing","approved"])->where("start_date","<",$b->end_date)->where("end_date",">",$b->start_date)->count(); if ($active >= $room->capacity) { throw \Illuminate\Validation\ValidationException::withMessages(["status"=>"Kapasitas kamar penuh pada periode tersebut."]); } } $b->update(["status"=>$data["status"]]); $message=match($data["status"]) { "processing"=>"Pengajuan booking Anda sedang diproses.", "approved"=>"Pengajuan booking Anda telah disetujui.", "cancelled"=>"Pengajuan booking Anda ditolak oleh admin." }; AppNotification::create(["user_id"=>$b->user_id,"title"=>"Pembaruan Status Booking","message"=>$message,"type"=>"booking","is_read"=>false]); }); return back()->with("success","Status booking berhasil diperbarui."); } }
